 */
var reverseParentheses = function(s) {
    const stack = [''];
    let rev = false;

    const appendStr = (str) => {
        if (!rev) {
            stack[stack.length - 1] += str;
        } else {
            stack[stack.length - 1] = str + stack[stack.length - 1];
        }
    };

    for (const char of s) {
        if (char === '(') {
            stack.push('');
            rev = !rev;
        } else if (char === ')') {
            rev = !rev;
            appendStr(stack.pop());
        } else {
            appendStr(char);
        }
    }

    return stack[0];
};
